custom_css:
@media (min-width: 1101px) {
  #evolution {
    padding-top: clamp(68px, 7vw, 96px) !important;
    padding-bottom: clamp(42px, 4vw, 62px) !important;
  }

  #evolution .roadmap-copy .eyebrow {
    margin-bottom: 18px !important;
  }

  #evolution .roadmap-copy h2 {
    margin-bottom: 22px !important;
  }

  #evolution .roadmap-copy p:not(.eyebrow) {
    margin-bottom: 0 !important;
  }

  #evolution .prototype-timeline {
    grid-template-columns: repeat(4, minmax(0, 1fr)) !important;
    column-gap: clamp(34px, 4vw, 64px) !important;
    row-gap: clamp(24px, 2.4vw, 36px) !important;
    margin-top: clamp(42px, 4vw, 58px) !important;
    align-items: start !important;
  }

  #evolution .prototype-timeline li {
    min-height: 0 !important;
    padding-top: 18px !important;
    align-self: start !important;
  }

  #evolution .prototype-timeline li:nth-child(n+5) {
    margin-top: 0 !important;
  }

  #evolution .evolution-close {
    display: block !important;
    margin-top: clamp(28px, 3vw, 42px) !important;
    padding-top: 28px !important;
  }
}

@media (max-width: 1100px) {
  #evolution {
    padding-block: clamp(64px, 9vw, 88px) !important;
  }

  #evolution .prototype-timeline {
    row-gap: 30px !important;
    margin-top: 44px !important;
  }

  #evolution .evolution-close {
    margin-top: 34px !important;
    padding-top: 26px !important;
  }
}
